function buildDigest(items, generatedAt) {
  const rows = items
    .flatMap(({ json }) => (Array.isArray(json) ? json : [json]))
    .filter((row) => row && typeof row === 'object' && (row.title || row.url || row.googleNewsUrl));

  const signalCounts = {};
  const decodedArticles = [];
  const undecodedFallbacks = [];

  for (const row of rows) {
    const signals = Array.isArray(row.marketSignals) ? row.marketSignals.filter(Boolean) : [];
    for (const sig of signals) {
      signalCounts[sig] = (signalCounts[sig] || 0) + 1;
    }
    const normalized = {
      title: row.title ?? null,
      publisher: row.sourceName ?? null,
      publishedAt: row.publishedAt ?? null,
      url: row.url ?? row.googleNewsUrl ?? null,
      urlDecoded: Boolean(row.urlDecoded),
      fullArticleExtracted: Boolean(row.fullArticleExtracted),
      wordCount: Number.isFinite(row.wordCount) ? row.wordCount : 0,
      marketSignals: signals,
      agentSummary: row.agentSummary ?? null,
      articleExcerpt: typeof row.articleText === 'string' ? row.articleText.slice(0, 600) : null
    };
    if (normalized.urlDecoded) {
      decodedArticles.push(normalized);
    } else {
      undecodedFallbacks.push(normalized);
    }
  }

  return {
    generatedAt,
    state: !rows.length ? 'no-articles-returned' : 'ok',
    totalArticles: rows.length,
    decodedCount: decodedArticles.length,
    fullTextCount: rows.filter((r) => Boolean(r.fullArticleExtracted)).length,
    signalCounts,
    articles: decodedArticles,
    undecodedFallbacks
  };
}

return [{ json: buildDigest($input.all(), new Date().toISOString()) }];
